import hmac
import hashlib
import os
from flask import Flask, request, jsonify
import sqlite3

app = Flask(__name__)
SECRET_KEY = os.urandom(32)
MAX_CHUNK_SIZE = 0x7FFFFFFF  # 2GB max per chunk
MAX_TOTAL_SIZE = 0x100000000  # 4GB total budget

def get_db():
    conn = sqlite3.connect(':memory:')
    conn.execute('CREATE TABLE IF NOT EXISTS allocations (id TEXT PRIMARY KEY, total_size INTEGER, chunk_count INTEGER)')
    return conn

def verify_token(token, data):
    """HMAC verification for request authenticity"""
    expected = hmac.new(SECRET_KEY, data.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(token, expected)

def validate_chunk_sizes(chunks):
    """Validate each individual chunk is within bounds.
    Each chunk size is a 32-bit unsigned integer."""
    for chunk in chunks:
        if not isinstance(chunk, int):
            return False, "Chunk size must be integer"
        if chunk < 0:
            return False, "Chunk size must be non-negative"
        if chunk > MAX_CHUNK_SIZE:
            return False, f"Chunk size {chunk} exceeds maximum {MAX_CHUNK_SIZE}"
    return True, "OK"

def compute_total_allocation(chunks):
    """Compute total allocation needed using Python's arbitrary precision.
    No overflow possible - Python integers have unlimited precision."""
    total = 0
    for chunk in chunks:
        total += chunk
    return total

def check_budget(allocation_id, new_total, db):
    """Ensure total allocation doesn't exceed budget"""
    cursor = db.execute('SELECT total_size FROM allocations WHERE id = ?', (allocation_id,))
    row = cursor.fetchone()
    existing = row[0] if row else 0
    combined = existing + new_total
    if combined > MAX_TOTAL_SIZE:
        return False, f"Budget exceeded: {combined} > {MAX_TOTAL_SIZE}"
    return True, "OK"

def allocate_buffer(size):
    """Simulate buffer allocation - in real system this calls into C allocator"""
    return bytearray(size)

@app.route('/api/v2/allocate', methods=['POST'])
def handle_allocate():
    """Multi-chunk allocation endpoint.
    Accepts a list of chunk sizes, validates each individually,
    computes total, checks budget, then allocates."""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid JSON'}), 400

    allocation_id = data.get('id', '')
    if not allocation_id or len(allocation_id) > 64:
        return jsonify({'error': 'Invalid allocation ID'}), 400

    chunks = data.get('chunks', [])
    if not isinstance(chunks, list) or len(chunks) == 0:
        return jsonify({'error': 'Chunks must be non-empty list'}), 400
    if len(chunks) > 16:
        return jsonify({'error': 'Too many chunks'}), 400

    # Step 1: Validate each chunk individually
    valid, msg = validate_chunk_sizes(chunks)
    if not valid:
        return jsonify({'error': msg}), 400

    # Step 2: Compute total using safe arbitrary-precision arithmetic
    total_needed = compute_total_allocation(chunks)

    # Step 3: Check against budget
    db = get_db()
    budget_ok, budget_msg = check_budget(allocation_id, total_needed, db)
    if not budget_ok:
        return jsonify({'error': budget_msg}), 403

    # Step 4: Perform allocations
    buffers = []
    for chunk in chunks:
        buf = allocate_buffer(chunk)
        buffers.append(len(buf))

    # Step 5: Record allocation
    db.execute(
        'INSERT OR REPLACE INTO allocations (id, total_size, chunk_count) VALUES (?, ?, ?)',
        (allocation_id, total_needed, len(chunks))
    )
    db.commit()

    return jsonify({
        'id': allocation_id,
        'allocated_chunks': buffers,
        'total_recorded': total_needed
    }), 200

@app.route('/api/v2/status', methods=['GET'])
def handle_status():
    db = get_db()
    cursor = db.execute('SELECT id, total_size, chunk_count FROM allocations')
    rows = cursor.fetchall()
    return jsonify({'allocations': [{'id': r[0], 'size': r[1], 'chunks': r[2]} for r in rows]})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
